53	/// Cancellation token tripped by Ctrl-C or SIGTERM.
54	fn shutdown_signal() -> CancellationToken {
55	    let token = CancellationToken::new();
56	    let shutdown = token.clone();
57	
58	    tokio::spawn(async move {
59	        let ctrl_c = async {
60	            tokio::signal::ctrl_c().await.expect("failed to install Ctrl-C signal handler");
61	        };
62	
63	        let sigterm = async {
64	            tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
65	                .expect("failed to install SIGTERM signal handler")
66	                .recv()
67	                .await;
68	        };
69	
70	        tokio::select! {
71	            _ = ctrl_c => info!("received shutdown signal (Ctrl-C), shutting down..."),
72	            _ = sigterm => info!("received shutdown signal (SIGTERM), shutting down..."),
73	        }
74	
75	        shutdown.cancel();
76	    });
77	
78	    token
79	}
