pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    let api_keys = state.api_keys();

    if api_keys.is_empty() || req.method() == Method::OPTIONS || !is_guarded_path(req.uri().path())
    {
        return next.run(req).await;
    }

    if is_authorized(&req, api_keys) {
        next.run(req).await
    } else {
        (
            StatusCode::UNAUTHORIZED,
            Json(json!({ "error": "Unauthorized" })),
        )
            .into_response()
    }
}

/// Whether `path` falls under one of the authenticated route prefixes.
fn is_guarded_path(path: &str) -> bool {
    GUARDED_PREFIXES.iter().any(|prefix| {
        path == *prefix || path.strip_prefix(prefix).is_some_and(|rest| rest.starts_with('/'))
    })
}

