use axum::Json;
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::state::AppState;

/// Path prefixes guarded by API key authentication.
const GUARDED_PREFIXES: &[&str] = &["/v1", "/v2", "/inference"];

/// Require a valid `Authorization: Bearer <key>` header on guarded routes.
///
/// Requests outside the guarded prefixes (e.g. `/health`, `/metrics`) and
/// `OPTIONS` requests (CORS preflight) are always allowed through. When no API
/// keys are configured, authentication is disabled and every request passes.
/// Unauthorized requests to guarded routes receive HTTP 401 with a
/// `{"error": "Unauthorized"}` body.
pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    let api_keys = state.api_keys();

    if api_keys.is_empty() || req.method() == Method::OPTIONS || !is_guarded_path(req.uri().path())
    {
        return next.run(req).await;
    }

    if is_authorized(&req, api_keys) {
        next.run(req).await
    } else {
        (
            StatusCode::UNAUTHORIZED,
            Json(json!({ "error": "Unauthorized" })),
        )
            .into_response()
    }
}

/// Whether `path` falls under one of the authenticated route prefixes.
fn is_guarded_path(path: &str) -> bool {
    GUARDED_PREFIXES.iter().any(|prefix| {
        path == *prefix || path.strip_prefix(prefix).is_some_and(|rest| rest.starts_with('/'))
    })
}

/// Whether the request carries a bearer token matching a configured key.
fn is_authorized(req: &Request, api_keys: &[String]) -> bool {
    req.headers()
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
